.md-preview {
  color: var(--g-color-text-primary);
  overflow-wrap: anywhere;
}

.md-preview > :first-child {
  margin-top: 0;
}

.md-preview > :last-child {
  margin-bottom: 0;
}

.md-preview__heading {
  margin: var(--g-spacing-4) 0 var(--g-spacing-2);
}

.md-preview__p {
  margin: 0 0 var(--g-spacing-3);
}

.md-preview__p_tight {
  margin: 0;
}

.md-preview__code {
  padding: 1px 4px;
  border-radius: var(--g-border-radius-xs);
  background: var(--g-color-base-generic);
}

.md-preview__pre {
  margin: 0 0 var(--g-spacing-3);
  padding: var(--g-spacing-3);
  overflow-x: auto;
  border-radius: var(--g-border-radius-m);
  background: var(--g-color-base-generic);
  white-space: pre;
}

