  ]);
  expect(parseInline('****')).toEqual([{ type: 'text', value: '****' }]);
  expect(parseInline('** не жирный **')).toEqual([{ type: 'text', value: '** не жирный **' }]);
  expect(parseInline('~одна~ ~~две~~')).toEqual([
    { type: 'text', value: '~одна~ ' },
    { type: 'del', children: [{ type: 'text', value: 'две' }] },
  ]);
});

